"use client";
import { AnimatePresence, motion } from "framer-motion";
import { useState } from "react";
import { Button } from "./ui/button";
import { Send, Sparkles, TrendingUp, X, Zap } from "lucide-react";
import { Card } from "./ui/card";
import { Input } from "./ui/input";

interface Message {
  role: "user" | "ai";
  text: string;
}

export default function ChatComponent() {
  const [messages, setMessages] = useState<Message[]>([
    { role: "ai", text: "Salam! Mən sənin Dashboard köməkçinim. Necə kömək edə bilərəm?" }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false); // Başlanğıcda bağlı olsun

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMsg: Message = { role: "user", text: input };
    setMessages((prev) => [...prev, userMsg]);
    const currentInput = input;
    setInput("");
    setLoading(true);

    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        body: JSON.stringify({ prompt: currentInput }),
      });
      const data = await response.json();
      const aiMsg: Message = { role: "ai", text: data.text };
      setMessages((prev) => [...prev, aiMsg]);
    } catch (error) {
      console.error("Xəta:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    // Şəffaf konteyner. bg-white silindi!
    <div className="fixed right-0 top-0 h-screen pointer-events-none z-50">
      <AnimatePresence>
        {isOpen && (
          <>
            {/* Overlay - arxa fonu bir az qaraldır */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/40 backdrop-blur-sm pointer-events-auto w-screen"
              onClick={() => setIsOpen(false)}
            />

            {/* Sidebar Panel */}
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="absolute right-0 top-0 h-full w-full max-w-md bg-slate-950 border-l border-slate-800 shadow-2xl pointer-events-auto flex flex-col"
            >
              {/* Header */}
              <div className="p-4 border-b border-slate-800 bg-slate-900/50">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Sparkles className="text-blue-400 w-5 h-5" />
                    <h2 className="text-lg font-semibold text-white">AI Assistant</h2>
                  </div>
                  <Button variant="ghost" size="icon" onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white">
                    <X className="w-5 h-5" />
                  </Button>
                </div>
              </div>

              {/* Chat Messages Area */}
              <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
                {messages.map((msg, idx) => (
                  <motion.div
                    key={idx}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}
                  >
                    <div className={`max-w-[85%] rounded-2xl p-3 ${
                      msg.role === "user" ? "bg-blue-600 text-white" : "bg-slate-800 text-slate-200"
                    }`}>
                      <p className="text-sm leading-relaxed">{msg.text}</p>
                    </div>
                  </motion.div>
                ))}
                {loading && (
                  <div className="flex justify-start">
                    <div className="bg-slate-800 p-3 rounded-2xl animate-pulse text-slate-400 text-xs">AI düşünür...</div>
                  </div>
                )}
              </div>

              {/* Input Area */}
              <div className="p-4 border-t border-slate-800 bg-slate-900/50">
                <div className="flex gap-2">
                  <Input
                    placeholder="Sualını yaz..."
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                    className="bg-slate-800 border-slate-700 text-white"
                  />
                  <Button onClick={sendMessage} disabled={loading} className="bg-blue-600 hover:bg-blue-700">
                    <Send className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      {/* Toggle Button */}
      {!isOpen && (
        <motion.button
          initial={{ scale: 0 }}
          animate={{ scale: 1 }}
          onClick={() => setIsOpen(true)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center pointer-events-auto hover:bg-blue-500 transition-all"
        >
          <Sparkles className="w-6 h-6" />
        </motion.button>
      )}
    </div>
  );
}